class entity;

class SoundScriptManager
{
public:
  static SoundScriptManager* instance;
  static inline SoundScriptManager* inst() { return instance; }
  void playEvent(int event, entity* ent = 0, float fade = 0.0f);
};

class GraphicalMenuSystem
{
  char pad[212];

public:
  bool multiplayer;
  char pad2[3];
  bool multi_1;
};

class game
{
  char pad[600];
  int surferIdx[2];
  bool personality[2];

public:
  int GetSurferIdx(int hero_num) const { return surferIdx[hero_num]; }
  bool GetUsingPersonalitySuit(int hero_num) const { return personality[hero_num]; }
};

class PanelQuad
{
public:
  virtual void TurnOn(bool on);
};

extern game* g_game_ptr;
extern int NumBoards[];

class BoardFrontEnd
{
  char pad[356];
  GraphicalMenuSystem* sys;
  int current_board_index;
  char pad2[92];
  PanelQuad* arrows[2][2];
  char pad3[140];
  int arrow_counter;
  int arrow_num;

  static const int arrow_timer = 3;

public:
  bool IsLevelBoardUnlocked(int location);
  void OnHighlightBoard();
  void OnRight(int c);
};

#define MAX_BOARDS 9
#define MAP_LOC_LAST 17
#define PERSONALITY_BOARD 0
#define SS_FE_LEFTRIGHT 26

void BoardFrontEnd::OnRight(int c)
{
	int maxBoards = MAX_BOARDS + MAP_LOC_LAST;

	SoundScriptManager::inst()->playEvent(SS_FE_LEFTRIGHT);		
	bool oneBoard = false;
	if (sys->multiplayer)
	{
		if ((sys->multi_1) && (g_game_ptr->GetUsingPersonalitySuit(0) || (NumBoards[g_game_ptr->GetSurferIdx(0)] == 1)))
			oneBoard = true;	
		else if ((!sys->multi_1) && (g_game_ptr->GetUsingPersonalitySuit(1) || (NumBoards[g_game_ptr->GetSurferIdx(1)] == 1)))
			oneBoard = true;
	}
	else
		oneBoard = g_game_ptr->GetUsingPersonalitySuit(0) || (NumBoards[g_game_ptr->GetSurferIdx(0)] == 1);



	if (oneBoard)
	{
		if (current_board_index == PERSONALITY_BOARD)
			current_board_index = MAX_BOARDS;
		else 
			current_board_index++;
	}
	else
		current_board_index++;

	if (current_board_index >= maxBoards)
		current_board_index = 0;

	if (current_board_index >= MAX_BOARDS)
	{
		while (!IsLevelBoardUnlocked( current_board_index - MAX_BOARDS ) && 
		       current_board_index < (MAX_BOARDS + MAP_LOC_LAST) && 
					 current_board_index >= MAX_BOARDS)
		{
			current_board_index++;
			if (current_board_index == MAX_BOARDS + MAP_LOC_LAST)
			{
				current_board_index = 0;
			}

		}
	}

	arrow_counter = arrow_timer;
	arrows[1][1]->TurnOn(true);
	arrows[1][0]->TurnOn(false);
	arrow_num = 1;

	OnHighlightBoard();
}
